import React, { useState } from 'react';
import { Link, useLocation } from 'react-router-dom';
import PropTypes from 'prop-types';
import { useAuth } from '../context/AuthContext';

// NavLink组件
const NavLink = ({ to, label, isActive }) => (
  <Link
    to={to}
    className={`nav-link ${isActive ? 'active' : ''}`}
  >
    {label}
  </Link>
);

// NavSection组件
const NavSection = ({ title, items, activePath }) => (
  <div className="nav-section">
    <h3>{title}</h3>
    {items.map((item) => (
      <NavLink
        key={item.path}
        to={item.path}
        label={item.label}
        isActive={activePath === item.path}
      />
    ))}
  </div>
);

NavLink.propTypes = {
  to: PropTypes.string.isRequired,
  label: PropTypes.string.isRequired,
  isActive: PropTypes.bool.isRequired
};

NavSection.propTypes = {
  title: PropTypes.string.isRequired,
  items: PropTypes.arrayOf(PropTypes.shape({
    path: PropTypes.string.isRequired,
    label: PropTypes.string.isRequired
  })).isRequired,
  activePath: PropTypes.string.isRequired
};

const Sidebar = () => {
  const location = useLocation();
  const { user, logout } = useAuth();

  const isActive = (path) => {
    return location.pathname === path;
  };

  const navItems = [
    { path: '/coinflip', label: 'Coinflip' },
    { path: '/blackjack', label: 'Blackjack' }
  ];

  return (
    <div className="sidebar">
      <div className="sidebar-header">
        <div className="logo">
          <h1 className="logo-text">AMPcoin</h1>
        </div>
      </div>

      <nav className="sidebar-nav">
        <NavSection 
          title="Games" 
          items={navItems.slice(0, 2)} 
          activePath={location.pathname} 
        />

        <NavSection 
          title="Other" 
          items={[...navItems.slice(2, 4), navItems[4]]} 
          activePath={location.pathname} 
        />

        {user?.isAdmin && (
          <NavSection
            title="Admin"
            items={[{ path: '/admin', label: 'Admin Panel' }]}
            activePath={location.pathname}
          />
        )}
      </nav>

      <div className="sidebar-footer">
        <div className="user-info">
          <img 
            src={user?.avatar || '/default-avatar.png'} 
            alt="Avatar" 
            className="user-avatar"
            onError={(e) => {
              e.target.src = '/default-avatar.png';
            }}
          />
          <div className="user-details">
            <span className="username">{user?.displayName}</span>
            <span className="balance">{user?.balance?.toLocaleString()} AMP</span>
          </div>
        </div>

        <button className="logout-btn" onClick={logout}>
          Logout
        </button>
      </div>
    </div>
  );
};

export default Sidebar;
